/* V3.2 requirement workbench. All user data is escaped; no network calls. */
'use strict';
let activeRequirementId='',requirementPoolFilter='';
const requirementNow=()=>db.requirements.find(r=>r.id===activeRequirementId)||null;
const requirementConditions=s=>({domains:[...s.domains].sort(),minScope:+s.minScope,chief:!!s.chief,genre:s.genre||''});
const reqAttr=id=>`data-id="${esc(id)}"`;
const reqDate=s=>esc(String(s).replace('T',' ').slice(0,19)+' UTC');
const reqConditionText=c=>`${c.domains.join(' + ')||'不限能力域'} / ${M.SCOPE_LABEL[c.minScope]}${c.chief?' / 需主策':''}${c.genre?' / 偏好'+c.genre:''}`;
function readRequirementForm(){const form=document.querySelector('#longlistForm');if(!form)return longState;const f=new FormData(form);return {title:String(f.get('title')||'自定义需求').trim(),domains:f.getAll('domains').map(String),minScope:Number(f.get('minScope')),chief:f.has('chief'),genre:String(f.get('genre')||'')};}
function useRequirement(r){activeRequirementId=r.id;longState={title:r.title,...M.clone(r.conditions)};}
function requirementDirty(r,s=longState){return r&&(s.title!==r.title||JSON.stringify(requirementConditions(s))!==JSON.stringify(r.conditions));}
function reqClose(message){if(save()===false)return toast('保存失败：当前更改只在内存中，请先导出 JSON。');modalStack=[];$('#detail').close();render();toast(message);}
function reqGuard(){if(role!=='hr'){toast('需求维护由 HR 视角处理；这不是账号权限。');return false;}return true;}
function requirementsView(){return `<section class="panel"><div class="panel-head"><div><h2>需求工作台</h2><p class="muted">保存口径、记录交付、积累业务反馈。工作记录与人才事实分开。</p></div>${info('requirements')}</div><div class="actions">${act('reqNew','新建需求','','btn')}${act('nav','查看临时长名单','data-page="longlist"','btn secondary')}</div><p class="hint">没有预填业务成绩。交付时间是实际系统记录时间，人才事实观察日仍为 ${esc(db.observationDate)}。仅本地保存，不发送通知。</p></section><div class="req-grid section-space">${db.requirements.map(r=>`<article class="panel"><div class="row spread"><h3>${esc(r.title)}</h3>${tag(r.status)}</div><p class="muted">负责人 ${esc(r.owner)} / 业务方 ${esc(r.requester)}</p><p>${esc(reqConditionText(r.conditions))}</p><p class="small muted">口径 v${r.version} / ${r.deliveries.length} 次交付 / ${r.poolPersonIds.filter(id=>db.pool.includes(id)).length} 位关联人才</p><div class="actions">${act('reqOpen','打开需求',reqAttr(r.id),'btn')}${act('reqHistory','版本与交付',reqAttr(r.id),'link')}${act('reqPool','关联人才池',reqAttr(r.id),'link')}</div></article>`).join('')||'<div class="panel empty">尚未保存需求。新建后选择条件，再保存负责人和业务方，即可冻结第一份交付名单。</div>'}</div>`;}
function longlistView(){
 const r=requirementNow();let report=null,error='';try{report=M.explainLonglist(db,requirementConditions(longState));}catch(e){error=e.message;}
 const dirty=requirementDirty(r),diff=r&&!dirty?M.requirementDiff(db,r.id):null;
 return `<section class="panel"><div class="panel-head"><div><h2>${r?esc(r.title):'临时需求长名单'} ${r?tag('口径 v'+r.version):tag('尚未保存','amber')}</h2><p class="muted">先核对条件，再保存需求；交付只冻结当前名单，不代表已推荐或业务采纳。</p></div>${info('requirements')}</div>
 <div class="actions">${act('nav','需求工作台','data-page="requirements"','link')}${r?act('reqHistory','版本与历史交付',reqAttr(r.id),'link'):''}${act('reqNew','另建需求','','link')}</div>
 ${r?`<p class="small muted">负责人 ${esc(r.owner)} / 业务方 ${esc(r.requester)} / ${esc(r.status)} / 已记录 ${r.deliveries.length} 次交付</p>`:''}
 <div class="tabs">${M.LONGLIST_PRESETS.map(p=>act('llPreset',esc(p.title),reqAttr(p.id),longState.preset===p.id?'active':'')).join('')}</div>
 <form id="longlistForm" class="ll-form"><label class="field">需求名称<input name="title" value="${esc(longState.title)}" maxlength="80" required></label><fieldset class="field"><legend>必需能力域（可多选）</legend><div class="checks">${M.DOMAINS.map(d=>`<label><input type="checkbox" name="domains" value="${esc(d)}" ${longState.domains.includes(d)?'checked':''}>${esc(d)}</label>`).join('')}</div></fieldset><label class="field">最低责任范围<select name="minScope">${[1,2,3,4].map(n=>`<option value="${n}" ${+longState.minScope===n?'selected':''}>${M.SCOPE_LABEL[n]}</option>`).join('')}</select></label><label class="field">项目类型偏好（不淘汰）<select name="genre"><option value="">不限</option>${['动作','开放世界','回合制','科幻','东方玄幻'].map(g=>`<option ${longState.genre===g?'selected':''}>${g}</option>`).join('')}</select></label><label class="checks"><span><input type="checkbox" name="chief" ${longState.chief?'checked':''}>需做过主策（可由另一段经历证明）</span></label><div class="actions"><button class="btn">重新计算</button>${role==='hr'?act('reqSave',r?'保存需求 / 新版本':'保存为需求','','btn secondary'):''}${r&&role==='hr'?act('reqDeliver','记录本次交付','','btn secondary'):''}${report?act('llExport','导出当前解释 CSV','','link'):''}</div></form>
 ${error?`<p class="error">${esc(error)}</p>`:''}${dirty?'<p class="hint">当前条件为未保存预览；请先保存新版本再交付。旧版本与旧名单保持不变。</p>':''}</section>
 ${diff?.last?`<section class="panel section-space"><h3>与最近交付比较 · ${diff.changes.length} 人分层变化</h3><p class="muted">可能来自口径调整或证据更新，不自动覆盖历史名单。</p>${diff.changes.map(x=>`<span class="badge">${esc(x.name)}：${esc(x.before)} → ${esc(x.after)}</span>`).join('')||'<p class="muted">分层未变化；交付仍可能存在证据更新。</p>'}</section>`:''}
 ${report?gapReportView(report):''}
 ${report?['A','B'].map(t=>`<section class="panel section-space" data-tier="${t}"><div class="panel-head"><h2>${t} 层 · ${t==='A'?'硬条件全部有证据':'部分满足 / 有待核验缺口'} · ${report.tiers[t].length} 人</h2>${info('longlist')}</div>${report.tiers[t].map(row=>llCard(row)).join('')||'<p class="empty">当前样本暂无此层人员；不能由此判断市场无人。</p>'}</section>`).join('')+`<section class="panel section-space" data-tier="C"><h2>C 层 · 未进入 A/B 的样本 · ${report.tiers.C.length} 人</h2><p class="muted">不丢弃未入选人物，逐人列出证据缺口；C 层不是能力评价。</p>${report.tiers.C.map(row=>`<details class="req-explanation"><summary>${esc(row.person.name)} · 查看未入选原因</summary>${row.gaps.map(g=>`<p>${esc(g)}</p>`).join('')}${row.hits.map(h=>`<p>${esc(h.label)} ${claimLinks(h.claimIds)}</p>`).join('')}<div class="actions">${personBtn(row.personId)}${r&&role==='hr'?act('poolNeed','加入此需求人才池',reqAttr(row.personId),'link'):''}</div></details>`).join('')||'<p class="muted">无 C 层样本。</p>'}</section>`:''}`;
}
function gapReportView(report){return `<section class="panel section-space"><div class="panel-head"><h2>反向解释 · 逐人覆盖 ${report.evaluatedPeople}/${report.totalPeople}</h2>${info('gapAnalysis')}</div><p class="hint">缺证 ≠ 没有能力；A 层为空 ≠ 市场没人或 JD 过严。这里仅描述当前虚构样本，供补证和需求讨论。</p><div class="req-gap-grid">${[['missing_evidence','资料未证实','优先补充职责、头衔或任期证据'],['below_requirement','已收录范围低于要求','讨论责任范围，不评价真实能力'],['preference','项目偏好未命中','仅偏好，不作为淘汰原因']].map(([kind,title,hint])=>`<div class="req-gap-block"><h3>${title}</h3><p class="small muted">${hint}</p>${report.gapDistribution.filter(g=>g.kind===kind).map(g=>`<details class="req-explanation"><summary>${esc(g.label)} <b>${g.count}/${g.denominator}</b></summary><p>${g.personIds.map(id=>personBtn(id)).join('、')}</p></details>`).join('')||'<p class="muted">无此类原因</p>'}</div>`).join('')}</div><p class="small muted">分母为库内去重人数 ${report.totalPeople}；每条原因按人去重，同一人可有多个原因，不能相加。判断来源仅为已发布事实与当前有效字段。</p></section>`;}
function requirementPoolControl(){return `<div class="actions req-pool-filters">${act('reqPoolAll','全部人才池','','link')}${db.requirements.map(r=>act('reqPool',esc(r.title),reqAttr(r.id),requirementPoolFilter===r.id?'btn':'btn secondary')).join('')}</div>`;}
function currentPoolForRequirements(){return requirementPoolFilter&&db.requirements.some(r=>r.id===requirementPoolFilter)?M.requirementPool(db,requirementPoolFilter):M.poolItems(db);}
function frozenRows(d){return d.rows.map(row=>`<details class="req-explanation"><summary>${esc(row.person.name)} · ${esc(row.tier)} 层</summary>${row.hits.map(h=>`<p><b>${esc(h.label)}</b></p>${h.claimIds.map(id=>{const c=d.claimSnapshots.find(c=>c.id===id),s=d.sourceSnapshots.find(e=>e.id===c.sourceId);return `<div class="quote">${esc(c.quote)}<p class="small muted">${esc(M.fieldLabels[c.field])} / ${esc(c.basis)} / 来源 ${esc(s.id)} / 发布 ${esc(s.published)}</p></div>`;}).join('')}`).join('')}${row.gaps.map(g=>`<p>${esc(g)}</p>`).join('')}${row.checks.map(g=>`<p class="muted">${esc(g)}</p>`).join('')}</details>`).join('');}
Object.assign(window.extraModals,{
 reqSave(){const r=requirementNow();return ['保存需求口径',`<p>${esc(longState.title)} · ${esc(reqConditionText(requirementConditions(longState)))}</p><form id="requirementSaveForm"><label class="field">负责人<input name="owner" required maxlength="40" value="${esc(r?.owner||'HRBP（演示）')}"></label><label class="field">业务方<input name="requester" required maxlength="40" value="${esc(r?.requester||'业务负责人（演示）')}"></label><label class="field">状态<select name="status">${M.REQUIREMENT_STATUSES.map(s=>`<option ${r?.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">${r?'修改依据（必填）':'创建说明'}<textarea name="reason" maxlength="600" ${r?'required':''}></textarea></label><p class="hint">需求和调整理由是人工工作记录；不得记录联系方式或推断候选人意向。条件改动自动生成新版本和调整明细，不算业务价值已经实现。</p><p class="error" id="requirementError" hidden></p><button class="btn">${r?'保存新版本':'确认保存需求'}</button></form>`];},
 reqHistory(m){const r=db.requirements.find(r=>r.id===m.id);if(!r)return ['需求已不存在','<p>请重新打开需求。</p>'];return ['版本与交付 · '+esc(r.title),`<h3>需求版本</h3>${r.versions.slice().reverse().map(v=>`<div class="record"><b>口径 v${v.version} · ${esc(v.title)}</b><p>${esc(reqConditionText(v.conditions))}</p><p class="small muted">${reqDate(v.updatedAt)} · ${esc(v.reason)}</p>${role==='hr'&&v.version!==r.version?act('reqRestore','以此口径建立新版本',`${reqAttr(r.id)} data-version="${v.version}"`,'link'):''}</div>`).join('')}<h3 class="section-space">冻结交付 · ${r.deliveries.length} 次</h3><p class="muted">以下是历史记录，不会随事实更新或需求改动重算。未发送通知。</p>${r.deliveries.slice().reverse().map(d=>`<div class="record"><b>口径 v${d.requirementVersion} · A ${d.tierA.length} / B ${d.tierB.length} / C ${d.tierC.length}</b><p class="small muted">${reqDate(d.createdAt)} · 事实版本 ${d.dataRevision}</p><div class="actions">${act('reqDelivery','查看冻结名单与原文',`${reqAttr(r.id)} data-delivery="${esc(d.id)}"`,'link')}${act('reqExportDelivery','导出历史解释 CSV',`${reqAttr(r.id)} data-delivery="${esc(d.id)}"`,'link')}</div></div>`).join('')||'<p>尚无交付。</p>'}<h3 class="section-space">条件调整 · ${r.calibrations.length} 条字段记录</h3><p class="muted">一次版本更新可能调整多个字段，条数不等于有效纠偏次数。</p>${r.calibrations.map(c=>`<p>v${c.fromVersion} → v${c.toVersion} / ${esc(c.field)}：${esc(JSON.stringify(c.before))} → ${esc(JSON.stringify(c.after))}<br><span class="muted">${esc(c.trigger)}</span></p>`).join('')||'<p class="muted">尚无条件调整。</p>'}`];},
 reqRestore(m){return ['恢复旧口径（新增版本）',`<p>将需求恢复为 v${m.version} 的口径，旧版本和交付不会删除。</p><form id="requirementRestoreForm"><input type="hidden" name="id" value="${esc(m.id)}"><input type="hidden" name="version" value="${m.version}"><label class="field">恢复依据<textarea name="reason" required maxlength="600"></textarea></label><p class="error" id="requirementError" hidden></p><button class="btn">建立新版本</button></form>`];},
 reqDelivery(m){const r=db.requirements.find(r=>r.id===m.id),d=r?.deliveries.find(d=>d.id===m.delivery);if(!d)return ['交付不存在','<p>请重新打开需求。</p>'];const w=M.deliveryWarnings(db,d);return ['历史交付 · '+esc(r.title),`<p class="hint">冻结于 ${reqDate(d.createdAt)}，口径 v${d.requirementVersion}，事实版本 ${d.dataRevision}。这不是当前推荐名单。</p>${w.sourceIds.length||w.claimIds.length?`<p class="error">历史依据已有变更：${w.sourceIds.length} 份来源当前不可用，${w.claimIds.length} 条字段已退出当前事实。请重新计算后再决策；下列原文仅作审计。</p>`:''}<p>${esc(reqConditionText(d.conditionsSnapshot))} / 分母 ${d.totalPeople} 人</p>${frozenRows(d)}<h3 class="section-space">业务反馈（人工记录）</h3>${r.businessFeedback.filter(f=>f.deliveryId===d.id).slice().reverse().map(f=>`<div class="record">${esc(d.rows.find(x=>x.personId===f.personId)?.person.name)} · ${esc(f.decision)}<p>${esc(f.reason)}</p><small>${esc(f.actor)} · ${reqDate(f.date)}</small></div>`).join('')||'<p class="muted">尚无反馈，不视为已采纳。</p>'}<form id="requirementFeedbackForm"><input type="hidden" name="id" value="${esc(r.id)}"><input type="hidden" name="deliveryId" value="${esc(d.id)}"><div class="formgrid"><label class="field">交付人物<select name="personId">${d.rows.map(x=>`<option value="${esc(x.personId)}">${esc(x.person.name)} · ${x.tier}</option>`).join('')}</select></label><label class="field">业务评价<select name="decision">${M.FEEDBACK_DECISIONS.map(x=>`<option>${x}</option>`).join('')}</select></label></div><label class="field">评价人（演示）<input name="actor" maxlength="40" required value="业务负责人（演示）"></label><label class="field">依据 / 反馈<textarea name="reason" required maxlength="600"></textarea></label><p class="hint">“同意接触”仅代表业务方决策，不代表候选人有意向，也不会发送消息。</p><p class="error" id="requirementError" hidden></p><button class="btn">记录反馈</button></form>`];}
});
function exportRequirementRows(rows,title,context){const safe=v=>{let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const content=[['需求','口径/观察范围','分层','姓名','人员ID','命中依据','未入选/缺口原因','证据不足','已收录范围低于要求','偏好未命中','字段ID','来源ID','下一步核验'],...rows.map(r=>[title,context,r.tier,r.person.name,r.personId,r.hits.map(h=>h.label).join('；'),r.gaps.join('；'),r.reasons.filter(x=>x.kind==='missing_evidence').map(x=>x.label).join('；'),r.reasons.filter(x=>x.kind==='below_requirement').map(x=>x.label).join('；'),r.reasons.filter(x=>x.kind==='preference').map(x=>x.label).join('；'),r.hits.flatMap(h=>h.claimIds).join('；'),[...new Set(r.hits.flatMap(h=>h.evidenceIds))].join('；'),r.checks.join('；')])].map(row=>row.map(safe).join(',')).join('\r\n');download('需求长名单_完整解释.csv','\ufeff'+content,'text/csv');}
Object.assign(window.insightActions,{
 reqNew(){activeRequirementId='';longState={...M.clone(M.LONGLIST_PRESETS[0]),title:'新的主策需求（演示）'};delete longState.id;go('longlist');},
 reqOpen(b){const r=db.requirements.find(r=>r.id===b.dataset.id);if(r){useRequirement(r);go('longlist');}},
 reqSave(){if(!reqGuard())return;try{longState=readRequirementForm();M.explainLonglist(db,requirementConditions(longState));openModal('reqSave');}catch(e){toast(e.message);}},
 reqDeliver(){if(!reqGuard())return;const r=requirementNow();if(!r)return toast('请先保存需求');if(requirementDirty(r,readRequirementForm()))return toast('条件已改动，请先保存新版本再交付');try{const d=M.deliverRequirement(db,r.id);if(save()===false)return toast('保存失败，请先导出JSON');render();openModal('reqDelivery',r.id,{delivery:d.id});}catch(e){toast(e.message);}},
 reqHistory(b){openModal('reqHistory',b.dataset.id);},
 reqRestore(b){if(reqGuard())openModal('reqRestore',b.dataset.id,{version:+b.dataset.version});},
 reqDelivery(b){openModal('reqDelivery',b.dataset.id,{delivery:b.dataset.delivery});},
 reqExportDelivery(b){const r=db.requirements.find(r=>r.id===b.dataset.id),d=r.deliveries.find(d=>d.id===b.dataset.delivery);exportRequirementRows(d.rows,r.versions.find(v=>v.version===d.requirementVersion).title,`历史交付 ${d.createdAt} / v${d.requirementVersion} / ${d.observationDate} / 非当前事实`);},
 reqPool(b){requirementPoolFilter=b.dataset.id;go('pool');},
 reqPoolAll(){requirementPoolFilter='';render();},
 llPreset(b){const p=M.LONGLIST_PRESETS.find(x=>x.id===b.dataset.id);longState={preset:p.id,title:requirementNow()?.title||p.title,domains:[...p.domains],minScope:p.minScope,chief:p.chief,genre:p.genre};render();},
 llExport(){try{const s=readRequirementForm(),report=M.explainLonglist(db,requirementConditions(s));exportRequirementRows(report.rows,s.title,`当前预览 / 观察日 ${db.observationDate} / 样本不代表市场`);}catch(e){toast(e.message);}},
 poolNeed(b){const r=requirementNow();if(r){if(!reqGuard())return;try{M.linkRequirementPerson(db,r.id,b.dataset.id);if(save()!==false){render();toast('已关联此需求，不覆盖其他需求及原跟进记录');}}catch(e){toast(e.message);}}else{try{M.poolAdd(db,b.dataset.id,{reason:'临时长名单：'+longState.title});refresh();toast('已加入全局人才池；保存需求后可建立需求关联');}catch(e){toast(e.message);}}}
});
const reqFormError=e=>{const el=document.querySelector('#requirementError');if(el){el.hidden=false;el.textContent=e.message;}else toast(e.message);};
Object.assign(window.insightForms,{
 longlistForm(){longState=readRequirementForm();render();},
 requirementSaveForm(f,get){if(!reqGuard())return;try{const r=M.saveRequirement(db,requirementNow()?.id||null,{title:longState.title,conditions:requirementConditions(longState),owner:get('owner'),requester:get('requester'),status:get('status'),reason:get('reason')});useRequirement(r);reqClose('需求已保存，历史版本保留');}catch(e){reqFormError(e);}},
 requirementRestoreForm(f,get){if(!reqGuard())return;try{const r=M.restoreRequirementVersion(db,get('id'),+get('version'),get('reason'));useRequirement(r);reqClose('已由历史口径建立新版本');}catch(e){reqFormError(e);}},
 requirementFeedbackForm(f,get){try{M.saveRequirementFeedback(db,get('id'),{deliveryId:get('deliveryId'),personId:get('personId'),decision:get('decision'),reason:get('reason'),actor:get('actor')});if(save()===false)return toast('保存失败，请先导出JSON');renderModal();toast('已记录业务评价；人员事实未改变');}catch(e){reqFormError(e);}}
});
